Below is a compact, self‑contained C++ program that demonstrates the most common operations on a `std::vector`.  
Feel free to copy it into a file called `vector_demo.cpp` and compile with:

```bash
g++ -std=c++17 -O2 -Wall -Wextra vector_demo.cpp -o vector_demo
```

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <iomanip>   // for std::setw

// A small helper to nicely print a vector of any type that supports <<.
template <typename T>
void print_vector(const std::vector<T>& v, const std::string& name)
{
    std::cout << std::setw(12) << name << ": [ ";
    for (const auto& e : v) std::cout << e << ' ';
    std::cout << "]\n";
}

int main()
{
    // 1. Create an empty vector of ints.
    std::vector<int> numbers;
    std::cout << "Initially, size = " << numbers.size()
              << ", capacity = " << numbers.capacity() << '\n';

    // 2. Add some elements.
    numbers.push_back(10);
    numbers.push_back(20);
    numbers.push_back(30);
    numbers.push_back(40);

    print_vector(numbers, "numbers");

    // 3. Reserve capacity to avoid reallocations (good practice when you know the size).
    numbers.reserve(10);
    std::cout << "After reserve(10), capacity = " << numbers.capacity() << '\n';

    // 4. Access elements by index (read/write).
    numbers[2] = 99;                // change third element
    std::cout << "After numbers[2] = 99:\n";
    print_vector(numbers, "numbers");

    // 5. Use an iterator to traverse (read‑only in this case).
    std::cout << "Iterating with a const_iterator:\n";
    for (auto it = numbers.cbegin(); it != numbers.cend(); ++it)
        std::cout << *it << ' ';
    std::cout << '\n';

    // 6. Erase an element (here the third one).
    numbers.erase(numbers.begin() + 2);   // removes the element we set to 99
    std::cout << "After erase(2):\n";
    print_vector(numbers, "numbers");

    // 7. Create a vector of strings and use it with different operations.
    std::vector<std::string> words{"hello", "world"};
    print_vector(words, "words");

    words.push_back("C++");
    words.insert(words.begin() + 1, "beautiful");   // insert at position 1
    print_vector(words, "words");

    // 8. Demonstrate vector of structs.
    struct Point { int x; int y; };
    std::vector<Point> points;
    points.push_back({0, 0});
    points.push_back({3, 4});
    std::cout << "points vector size = " << points.size() << '\n';
    std::cout << "points[1] = (" << points[1].x << ", " << points[1].y << ")\n";

    // 9. Using a range‑based for loop.
    std::cout << "All points:\n";
    for (const auto& p : points)
        std::cout << "(" << p.x << ", " << p.y << ")\n";

    // 10. Use swap to exchange two vectors efficiently.
    std::vector<int> a = {1, 2, 3};
    std::vector<int> b = {10, 20};
    std::swap(a, b);          // a now has {10,20}, b has {1,2,3}
    print_vector(a, "a after swap");
    print_vector(b, "b after swap");

    return 0;
}
```

### What the program does

| Step | What happens | Why it’s useful |
|------|--------------|-----------------|
| 1 | Create an empty `std::vector<int>`. | Vectors start empty and grow as needed. |
| 2 | `push_back()` 4 numbers. | Adds elements at the back efficiently. |
| 3 | `reserve(10)`. | Pre‑allocates capacity; useful to avoid reallocations when you know the size in advance. |
| 4 | `numbers[2] = 99;` | Direct indexing – fast random access. |
| 5 | Iterate with a `const_iterator`. | Shows standard iterator usage. |
| 6 | `erase()` to remove an element. | Removes one element while keeping the order. |
| 7 | Vector of `std::string`. | Vectors can store any type. |
| 8 | Vector of a user‑defined struct (`Point`). | Demonstrates storing complex objects. |
| 9 | Range‑based `for` loop. | Very convenient when you only need read access. |
| 10 | `std::swap()` two vectors. | Swapping vectors is a constant‑time operation. |

Compile and run the program to see all the output. Feel free to modify the code to experiment with more vector operations (e.g., `resize()`, `emplace_back()`, `front()`, `back()`, etc.).
